class ZoomAwareCanvas : public QWidget,
                        public ScrollViewZoomAware {
public:
    QSizeF scrollViewUnscaledSize() const override
    {
        return QSizeF(560, 360);
    }

    void setScrollViewZoomFactor(qreal factor) override
    {
        m_zoomFactor = factor;
        update();
    }
};

