auto* advance = new Button("Advance upload", this);
auto* status = new Label("Progress: 0%", this);
advance->setProperty("progress", 0);

connect(advance, &Button::clicked, this, [=]() {
    const int current = advance->property("progress").toInt();
    const int progress = current >= 100 ? 25 : current + 25;
    advance->setProperty("progress", progress);
    Toast::showOrUpdateToast(
        advance,
        "upload",
        progress == 100
            ? "Upload complete"
            : QString("Uploading: %1%").arg(progress),
        progress == 100 ? Toast::Success : Toast::Informational,
        5000,
        Toast::TopEnd);
    status->setText(QString("Progress: %1%").arg(progress));
});

